const events = [
  { type: 'click', page: '/home' },
  { type: 'view', page: '/home' },
  { type: 'click', page: '/cart' }
];

const byType = Object.groupBy(events, e => e.type);
console.log(byType.click.length); // 2
console.log(Object.getPrototypeOf(byType) === null); // true

var words = paragraphs
    .SelectMany(p => p.Split(' '));

var byType = events
    .GroupBy(e => e.Type)
    .ToDictionary(g => g.Key, g => g.ToList());

